INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷111·太祖本纪二·广顺元年八月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/jiuwudaishi-111-august-transfers/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年八月，段落 jiu-wudaishi-205deb4a7860-p002662；已核上下文及传主，纸本及异文待核。", "id": "50c8ce67-1438-536e-a5f9-ce92e7c576f7"}, {"title": "旧五代史·卷111·太祖本纪二·广顺元年六月、七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/jiuwudaishi-111-june-ministers/source.txt", "note": "《旧五代史》卷111·太祖本纪二·广顺元年六月、七月，段落 jiu-wudaishi-205deb4a7860-p002661；已核上下文及传主，纸本及异文待核。", "id": "80be4ba9-c14d-5f5c-b19f-cc7cd1581529"}, {"title": "辽史·卷5·世宗本纪·天禄五年六月", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/liaoshi-005-han-investiture/source.txt", "note": "《辽史》卷5·世宗本纪·天禄五年六月，段落 liaoshi-7cd182a20e67-p000617；已核上下文及传主，纸本及异文待核。", "id": "ef6f80fc-1a87-5956-904f-4d4321cbbf6c"}, {"title": "宋史·卷262·列传二十一·李谷传·河中往事与拜相", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/songshi-262-li-gu-hezhong/source.txt", "note": "《宋史》卷262·列传二十一·李谷传·河中往事与拜相，段落 songshi-9c6e46fee832-p058093；已核上下文及传主，纸本及异文待核。", "id": "fbe4849e-7e35-5af1-80f8-9d3f9e27d709"}, {"title": "宋史·卷482·世家五·北汉刘氏·卫融早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/9e997db426b307c77960efec150970c3a7a81085/content/books/zizhi-tongjian/vol-290/year-0951/part-07/sources/library/songshi-482-wei-rong-early/source.txt", "note": "《宋史》卷482·世家五·北汉刘氏·卫融早年，段落 songshi-9c6e46fee832-p075165；已核上下文及传主，纸本及异文待核。", "id": "8d173705-66dd-5d88-a30c-c0df6fe6f834"}, {"title": "资治通鉴·卷290·广顺元年·三月徐州战果与沿淮政策", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/tongjian-290-951-march-policies/source.txt", "note": "《资治通鉴》卷290·广顺元年·三月徐州战果与沿淮政策，段落 zizhi-tongjian-a63549944a71-p003445；已核上下文及传主，纸本及异文待核。", "id": "5183e5d6-9ce7-5392-aeb1-3712e9138aec"}, {"title": "新五代史·卷70·东汉世家·郑珙出使与去世", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/148dffeabd6a27b31ce24bf25fa5203d0cd91ab7/content/books/zizhi-tongjian/vol-290/year-0951/part-06/sources/library/xinwudaishi-070-zheng-gong/source.txt", "note": "《新五代史》卷70·东汉世家·郑珙出使与去世，段落 xin-wudaishi-b08f244b9241-p003447；已核上下文及传主，纸本及异文待核。", "id": "46016120-f807-5489-965c-38a5e1abf468"}, {"title": "新五代史·卷66·楚世家·王进逵修府出走", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/4ae3eabc78dcb3f9ddd203076e0412b51fdf8d20/content/books/zizhi-tongjian/vol-290/year-0951/part-05/sources/library/xinwudaishi-066-langzhou-flight/source.txt", "note": "《新五代史》卷66·楚世家·王进逵修府出走，段落 xin-wudaishi-b08f244b9241-p003336；已核上下文及传主，纸本及异文待核。", "id": "f7ff540e-0d30-5629-a06f-b58a414e4c27"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "窦贞固", "aliases": ["竇貞固"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：窦贞固，原节度推官、获任者。", "biography": null, "status": "draft", "id": "628caf07-3ba2-5bc4-8630-598667f5bdd0"}, {"name": "苏禹珪", "aliases": ["蘇禹珪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "密州人，任河东观察判官。947年刘知远任命他为中书侍郎、同平章事。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "b8c912f3-4f5e-5fbc-9714-9caaf03ed98c"}, {"name": "翟光邺", "aliases": ["翟光鄴", "翟光業", "翟光业"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：翟光邺，受遣察安的皇城使。", "biography": null, "status": "draft", "id": "4b6400da-2b69-5857-b364-3106a40c1d45"}, {"name": "马光惠", "aliases": ["馬光惠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "马希振之子、马希萼的侄子。951年王逵等罢免马光赞后，让他主持朗州事务，随后拥立他为节度使。生卒年未载。", "biography": null, "status": "draft", "id": "59cfaa85-b7b4-5c24-a5e5-f54754f04076"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "钱仁俊", "aliases": ["錢仁俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：钱仁俊，从子、受遣告谕者。", "biography": null, "status": "draft", "id": "8ba65976-a158-523f-a631-fac69d75de34"}, {"name": "耶律阮", "aliases": ["耶律兀欲", "兀欲", "永康王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "小字兀欲，东丹王耶律倍之子。《资治通鉴》947年条下称永康王，记耶律德光将李彦绅、秦继旻的家属和财产交给他。《辽史》卷五明确名阮、小字兀欲，按同一主体建档；王号具体授封时间仍须另据后文校核，生卒年暂未录。", "biography": null, "status": "draft", "id": "42a17de5-aa28-50e6-bab8-b134f0113f3f"}, {"name": "述轧", "aliases": ["述軋"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年耶律德光派他与奚王拽刺、高谟翰驻守洛阳。生卒年、具体家族未载。", "biography": null, "status": "draft", "id": "1ecc60de-19a4-506b-a5c6-e10933ad627e"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "卫融", "aliases": ["衛融"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉官员，青州博兴人，字明远。951年七月以翰林学士身份奉刘崇之命出使契丹，谢册礼并请求援兵。《宋史》记早年中进士，曾任南乐主簿、忠武军掌书记等职。生卒年尚未录入。", "biography": null, "status": "draft", "id": "318087c3-dd4d-529d-bf97-fe917d05375b"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "孙方简", "aliases": ["孫方簡", "孙方谏", "孫方諫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》称中山人，聚众于狼山，归附后晋后任东北招收指挥使，后来转投契丹并拘执刘延翰。《宋史》孙行友传写作孙方谏，记他是孙行友的兄子；《资治通鉴》记孙行友是其弟，亲属记载冲突待核。姓名字形与主体按狼山、职衔和事迹对应复用，生卒年未核。", "biography": null, "status": "draft", "id": "17e0109c-1d9d-5437-a7d0-5c7be7b6beb8"}, {"name": "孙行友", "aliases": ["孫行友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "与孙方简聚众于狼山，借孙深意的术及边民避乱扩展部众。《宋史》记为莫州清苑人，出身务农，后任孙方谏的副手；《资治通鉴》记为孙方简之弟，《宋史》却记孙方谏为他的兄子，亲属与籍贯表述分别保留待核。生卒年未核。", "biography": null, "status": "draft", "id": "297fda14-1470-5546-b76b-7b2461eb1d3d"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
